PRAGMA defer_foreign_keys = ON;
CREATE TABLE oag_can_policies_rebuild(policy_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version>=1),policy_version INTEGER NOT NULL,effective_from TEXT NOT NULL,effective_until TEXT,root_activation_rule TEXT NOT NULL,responsibility_confirmation_rule TEXT NOT NULL,delegation_confirmation_rule TEXT NOT NULL,max_delegation_depth INTEGER NOT NULL CHECK(max_delegation_depth=1),proof_validity_rule TEXT NOT NULL,graph_supersession_rule TEXT NOT NULL,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL,max_effective_authority_proof_lifetime_seconds INTEGER,supersedes_policy_id TEXT REFERENCES oag_can_policies(policy_id),CHECK((version=1 AND max_effective_authority_proof_lifetime_seconds IS NULL AND supersedes_policy_id IS NULL) OR version>1));
INSERT INTO oag_can_policies_rebuild SELECT policy_id,version,policy_version,effective_from,effective_until,root_activation_rule,responsibility_confirmation_rule,delegation_confirmation_rule,max_delegation_depth,proof_validity_rule,graph_supersession_rule,correlation_id,causal_references_json,NULL,NULL FROM oag_can_policies;
DROP TABLE oag_can_policies;
ALTER TABLE oag_can_policies_rebuild RENAME TO oag_can_policies;
CREATE TRIGGER oag_can_policy_no_update BEFORE UPDATE ON oag_can_policies BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_policy_no_delete BEFORE DELETE ON oag_can_policies BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TABLE oag_can_authority_proofs(authority_proof_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),proof_digest TEXT NOT NULL UNIQUE,authority_source_class TEXT NOT NULL CHECK(authority_source_class='ORGANIZATIONAL_OPERATIONAL_AUTHORITY'),authority_basis TEXT NOT NULL CHECK(authority_basis IN('DIRECT','DELEGATED')),actor_id TEXT NOT NULL,binding_id TEXT NOT NULL,principal_id TEXT NOT NULL,membership_id TEXT NOT NULL,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,root_reference TEXT NOT NULL,responsibility_references_json TEXT NOT NULL,declaration_version_ids_json TEXT NOT NULL,confirmation_chain_id TEXT NOT NULL,delegation_references_json TEXT NOT NULL,graph_version_id TEXT NOT NULL REFERENCES oag_can_graph_versions(graph_version_id),graph_digest TEXT NOT NULL,policy_id TEXT NOT NULL REFERENCES oag_can_policies(policy_id),policy_version INTEGER NOT NULL,effective_scope_json TEXT NOT NULL,issued_at TEXT NOT NULL,expires_at TEXT NOT NULL CHECK(expires_at>issued_at),eligibility_state TEXT NOT NULL CHECK(eligibility_state='ELIGIBLE'),invalidation_reasons_json TEXT NOT NULL,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL);
CREATE TABLE oag_can_authority_proof_audit_events(audit_event_id TEXT PRIMARY KEY,event_kind TEXT NOT NULL,outcome TEXT NOT NULL,reason_code TEXT NOT NULL,authority_proof_id TEXT,actor_id TEXT NOT NULL,policy_id TEXT NOT NULL,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL,recorded_at TEXT NOT NULL,content_payload TEXT CHECK(content_payload IS NULL));
CREATE TRIGGER oag_can_proof_no_update BEFORE UPDATE ON oag_can_authority_proofs BEGIN SELECT RAISE(ABORT,'OAG_AUTHORITY_PROOF_IMMUTABLE'); END;
CREATE TRIGGER oag_can_proof_no_delete BEFORE DELETE ON oag_can_authority_proofs BEGIN SELECT RAISE(ABORT,'OAG_AUTHORITY_PROOF_IMMUTABLE'); END;
CREATE TRIGGER oag_can_proof_audit_no_update BEFORE UPDATE ON oag_can_authority_proof_audit_events BEGIN SELECT RAISE(ABORT,'OAG_AUTHORITY_PROOF_AUDIT_IMMUTABLE'); END;
CREATE TRIGGER oag_can_proof_audit_no_delete BEFORE DELETE ON oag_can_authority_proof_audit_events BEGIN SELECT RAISE(ABORT,'OAG_AUTHORITY_PROOF_AUDIT_IMMUTABLE'); END;
PRAGMA defer_foreign_keys = OFF;
